{
  "name": "opencode-gearbox",
  "version": "0.4.2",
  "description": "Gearbox for OpenCode: picks the reasoning effort and model for every prompt and every subagent.",
  "keywords": [
    "opencode-plugin",
    "opencode",
    "reasoning-effort",
    "model-routing",
    "ai-agents",
    "llm",
    "token-efficiency"
  ],
  "license": "MIT",
  "author": {
    "name": "Miguel Martens",
    "url": "https://github.com/miguelmartens"
  },
  "homepage": "https://getgearbox.dev",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/miguelmartens/opencode-gearbox.git"
  },
  "bugs": {
    "url": "https://github.com/miguelmartens/opencode-gearbox/issues"
  },
  "type": "module",
  "exports": {
    ".": "./src/server/index.ts",
    "./tui": "./src/tui/index.tsx",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "src",
    "bench/effortless-judge-cases.json",
    "bench/gearbox-judge-cases.json",
    "NOTICE.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "prepare": "git config core.hooksPath .githooks",
    "test": "bun test",
    "format": "bun fmt --no-script",
    "format:check": "bun fmt --check --no-script",
    "check": "bun run format:check && bun test",
    "bench:run": "bun bench/run.ts",
    "bench:summarize": "bun bench/summarize.ts",
    "bench:render": "bun bench/render.ts",
    "bench:verify": "bun bench/verify-tasks.ts"
  },
  "packageManager": "bun@1.4.4",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.7"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.1",
    "@opentui/solid": ">=0.8.1",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/client": "2.2.7"
  }
}
